class RuntimeFailure(RuntimeError):
    """The requested runtime or generation path is unsafe or unsupported."""

class GenerationRequest:
    sequence: str
    num_tokens: int
    temperature: float
    top_k: int
    top_p: float
    random_seed: int

    @classmethod
    def from_mapping(cls, value: Any) -> "GenerationRequest":
        expected = {
            "sequence",
            "num_tokens",
            "temperature",
            "top_k",
            "top_p",
            "random_seed",
            "enable_logits",
            "enable_sampled_probs",
            "enable_elapsed_ms_per_token",
        }
        if not isinstance(value, dict) or set(value) != expected:
            raise RuntimeFailure("generate payload keys differ")
        sequence = value["sequence"]
        if (
            not isinstance(sequence, str)
            or not 1 <= len(sequence) <= 8192
            or DNA.fullmatch(sequence) is None
        ):
            raise RuntimeFailure("sequence must be 1-8192 DNA characters")
        num_tokens = value["num_tokens"]
        top_k = value["top_k"]
        seed = value["random_seed"]
        if any(isinstance(item, bool) or not isinstance(item, int) for item in (num_tokens, top_k, seed)):
            raise RuntimeFailure("num_tokens, top_k, and random_seed must be integers")
        if not 1 <= num_tokens <= 512 or not 1 <= top_k <= 512 or not 0 <= seed < 2**63:
            raise RuntimeFailure("generation integer parameter is out of range")
        temperature = value["temperature"]
        top_p = value["top_p"]
        if any(
            isinstance(item, bool)
            or not isinstance(item, (int, float))
            or not math.isfinite(float(item))
            for item in (temperature, top_p)
        ):
            raise RuntimeFailure("temperature and top_p must be finite numbers")
        if float(temperature) <= 0 or not 0 <= float(top_p) <= 1:
            raise RuntimeFailure("temperature or top_p is out of range")
        if value["enable_logits"] is not False or value["enable_sampled_probs"] is not False:
            raise RuntimeFailure("the lean endpoint does not expose logits or sampled probabilities")
        if value["enable_elapsed_ms_per_token"] is not True:
            raise RuntimeFailure("per-token timings are required by the qualification oracle")
        return cls(
            sequence=sequence.upper(),
            num_tokens=num_tokens,
            temperature=float(temperature),
            top_k=top_k,
            top_p=float(top_p),
            random_seed=seed,
        )
